<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V;
$result = CmsContent::pages(['q' => V::queryString('q'), 'status' => V::queryString('status')], V::queryPage()); ?>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', V::queryString('q'), ['type' => 'search']) ?><?= V::field('Situação', 'status', V::queryString('status'), ['type' => 'select', 'choices' => ['' => 'Todas', 'draft' => 'Rascunho', 'published' => 'Publicada']]) ?><button class="cms-btn">Filtrar</button><a class="cms-btn-primary" href="/paginas/novo">Nova página</a></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma página encontrada.', 'Enquanto não houver página publicada, o site mantém os textos dos templates.') ?><?php else: ?>
<div class="cms-table-wrap" tabindex="0" role="region" aria-label="Páginas"><table><thead><tr><th>Título</th><th>Endereço</th><th>Situação</th><th>Atualizada</th><th></th></tr></thead><tbody>
<?php foreach ($result['rows'] as $row): ?><tr><td><a href="/paginas/<?= (int) $row['id'] ?>"><?= V::e($row['title']) ?></a></td><td>/<?= V::e($row['slug']) ?></td><td><?= V::badge($row['status'], $row['status'] === 'published' ? 'Publicada' : 'Rascunho') ?></td><td><?= V::date($row['updated_at']) ?></td><td><a href="/paginas/<?= (int) $row['id'] ?>/previa">Prévia</a></td></tr><?php endforeach; ?>
</tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
